// ---------------------------------------------------------------- worked examples re-derived (the build stops on any mismatch)
function must(cond, msg) { if (!cond) throw new Error(`worked example check failed: ${msg}`); }
const we1 = [6, -2, 3];
must(mag(we1) === 7 && eqV(R(unit(we1)), R([6 / 7, -2 / 7, 3 / 7])), 'WE1 direction cosines 6/7, -2/7, 3/7');
const we2a = [3, -6, 9], we2b = [-2, 4, -6];
must(collinear(we2a, we2b) && eqV(scl(-1.5, we2b), we2a) && dot(we2a, we2b) < 0, 'WE2 collinear, opposite, a = -3/2 b');
const we3A = [1, -2, 3], we3B = [4, 2, 3];
must(eqV(sub(we3B, we3A), [3, 4, 0]) && mag(sub(we3B, we3A)) === 5, 'WE3 AB = 3i + 4j, |AB| = 5');
const we4P = [1, 3, -2], we4Q = [4, -3, 7];
must(eqV(sectionIn(we4P, we4Q, 1, 2), [2, 1, 1]) && eqV(sectionEx(we4P, we4Q, 1, 2), [-2, 9, -11]), 'WE4 internal (2, 1, 1), external (-2, 9, -11)');
const we5a = [2, -1, 2], we5b = [1, 2, -2];
must(dot(we5a, we5b) === -4 && mag(we5a) === 3 && mag(we5b) === 3, 'WE5 cos = -4/9');
const we6a = [4, -1, 3], we6b = [2, 2, 1];
must(near(proj(we6a, we6b), 3), 'WE6 projection 3');
// WE7: |a| = 2, |b| = 5, |a + b| = √19 → a·b = (19 − 4 − 25)/2 = −5, cos θ = −1/2
{ const ab = (19 - 4 - 25) / 2, th = Math.acos(ab / 10); const a = [2, 0, 0], b = [5 * Math.cos(th), 5 * Math.sin(th), 0]; must(ab === -5 && near(th, (2 * Math.PI) / 3) && near(mag(add(a, b)), Math.sqrt(19)), 'WE7 120 degrees'); }
const we8a = [1, 2, -1], we8b = [2, -1, 3];
must(eqV(cross(we8a, we8b), [5, -5, -5]) && near(mag(cross(we8a, we8b)), 5 * Math.sqrt(3)), 'WE8 a × b = 5i − 5j − 5k');
const we9A = [1, 0, 1], we9B = [2, 2, 0], we9C = [0, 1, 3];
must(eqV(cross(sub(we9B, we9A), sub(we9C, we9A)), [5, -1, 3]) && near(triArea(we9A, we9B, we9C), Math.sqrt(35) / 2), 'WE9 area √35/2');

